<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,user,message,notify,date,type Work} from '../api'
import Icon from '../components/Icon.vue'
import VerifiedBadge from '../components/VerifiedBadge.vue'
import Avatar from '../components/Avatar.vue'
import ShareCard from '../components/ShareCard.vue'
import WorkByline from '../components/WorkByline.vue'
import CollectionProperty from '../components/CollectionProperty.vue'
import ArticleBody from '../components/ArticleBody.vue'
import {mediaPath} from '../article/html'
import '../article/article.css'
const route=useRoute(),router=useRouter(),work=ref<Work|null>(null),comments=ref<any[]>([]),error=ref(''),text=ref(''),busy=ref(false),shareOpen=ref(false)
const shareContent=computed(()=>work.value?{kind:'article' as const,title:work.value.title,credit:work.value.displayByline,publisher:work.value.authorName,description:work.value.excerpt,detail:`${work.value.customGenre||work.value.genre} · ${work.value.wordCount} 字`,path:`/work/${work.value.id}`}:null)
async function load(){try{work.value=(await api.get(`/public/works/${route.params.id}`)).data;if(work.value?.status==='PUBLISHED')comments.value=(await api.get(`/public/works/${route.params.id}/comments`)).data}catch(e){error.value=message(e)}}
function login(){router.push({path:'/login',query:{next:route.fullPath}})}
async function react(kind:string){if(!user.value)return login();if(!work.value)return;try{await api.put(`/member/works/${work.value.id}/reaction`,{kind,active:kind==='LIKE'?!work.value.liked:!work.value.bookmarked});await load()}catch(e){notify(message(e))}}
async function comment(){if(!text.value.trim())return;busy.value=true;try{await api.post(`/member/works/${route.params.id}/comments`,{body:text.value});text.value='';await load()}catch(e){notify(message(e))}finally{busy.value=false}}
async function remove(id:number){try{await api.delete(`/member/comments/${id}`);await load()}catch(e){notify(message(e))}}
function share(){shareOpen.value=true}
const sequence=ref<any>(null)
const chapterIndex=computed(()=>sequence.value?.works.findIndex((w:Work)=>w.id===work.value?.id)??-1)
const previous=computed(()=>chapterIndex.value>0?sequence.value.works[chapterIndex.value-1]:null)
const next=computed(()=>chapterIndex.value>=0?sequence.value?.works[chapterIndex.value+1]:null)
onMounted(async()=>{await load();try{const id=work.value?.collection?.id;if(id){const c=(await api.get(`/public/collections/${id}`)).data;if(c.works.some((w:Work)=>w.id===work.value?.id))sequence.value=c}}catch{/* 合集不可用时仍可阅读单篇 */}})
</script>
<template><div class="reading-container"><RouterLink to="/explore" class="back-link"><Icon name="ChevronLeft" :size="16"/>回到作品书架</RouterLink><div v-if="error" class="empty-state"><h2>这一页暂时无法打开</h2><p>{{error}}</p></div><article v-else-if="work"><header class="reading-header"><div class="reading-labels"><span class="genre-label">{{work.customGenre||work.genre}}</span><span v-if="work.isDemo" class="demo-label">示例作品 · 用于体验排版</span><span v-if="work.status!=='PUBLISHED'" class="tag-pill">仅自己可见</span></div><h1>{{work.title}}</h1><div class="reading-byline"><WorkByline :work="work"/><RouterLink :to="`/author/${work.authorId}`" class="publisher-link" :title="`发布账号：${work.authorName}`">{{work.authorName}} <VerifiedBadge :verified="work.authorVerified||work.authorAccountType==='PUBLIC'"/></RouterLink><span>{{date(work.publishedAt||work.updatedAt)}}</span><span>{{work.wordCount}} 字 · 约 {{Math.max(1,Math.ceil(work.wordCount/400))}} 分钟</span><RouterLink v-if="user?.id===work.authorId" :to="`/write/${work.id}`">编辑作品</RouterLink></div><CollectionProperty :collection="work.collection"/></header><img v-if="mediaPath.test(work.cover||'')" :src="work.cover" class="reading-cover" alt="作品封面"/><ArticleBody :html="work.body" :namespace="`work-${work.id}`" :genre="work.genre" :layout="work.layout"/><section v-if="work.notes||work.sourceNote" class="work-notes" aria-label="附注"><h2>附注</h2><p class="notes-text">{{[work.notes,work.sourceNote].filter(Boolean).join('\n\n')}}</p></section><section v-if="sequence" class="chapter-nav"><RouterLink :to="`/collection/${sequence.id}`">{{sequence.title}} · 目录</RouterLink><div><RouterLink v-if="previous" :to="{path:`/work/${previous.id}`,query:{collection:sequence.id}}">← 上一篇：{{previous.title}}</RouterLink><RouterLink v-if="next" :to="{path:`/work/${next.id}`,query:{collection:sequence.id}}">下一篇：{{next.title}} →</RouterLink></div></section><div class="reading-tags"><RouterLink v-for="tag in work.tags" :key="tag.id" :to="{path:'/explore',query:{tag:tag.id}}">#{{tag.name}}</RouterLink></div><div class="reading-actions" v-if="work.status==='PUBLISHED'"><button :class="{selected:work.liked}" @click="react('LIKE')"><Icon name="Heart"/>{{work.liked?'已喜欢':'喜欢'}} · {{work.likes}}</button><button :class="{selected:work.bookmarked}" @click="react('BOOKMARK')"><Icon name="Bookmark"/>{{work.bookmarked?'已收藏':'收藏'}}</button><button @click="share"><Icon name="ArrowUpRight"/>分享</button></div><section v-if="work.status==='PUBLISHED'" class="comments"><h2>评论 <span>{{comments.length}}</span></h2><form v-if="user" @submit.prevent="comment"><textarea v-model="text" maxlength="1000" placeholder="输入评论" aria-label="评论内容" required></textarea><button class="button small" :disabled="busy">发表评论<Icon name="Send" :size="14"/></button></form><p v-else class="comment-login"><button @click="login">登录</button>后，写下你的阅读感受。</p><p v-if="!comments.length" class="quiet-note">暂无评论</p><article v-for="c in comments" :key="c.id" class="comment"><div><RouterLink :to="`/author/${c.memberId}`"><Avatar :src="c.avatarUrl" :name="c.penName" :size="24"/>{{c.penName}}</RouterLink><time>{{date(c.createdAt)}}</time><button v-if="user&&(user.id===c.memberId||['ADMIN','SUPER_ADMIN'].includes(user.actorRole||user.role))" @click="remove(c.id)">移除</button></div><p>{{c.body}}</p></article></section></article><div v-else class="empty-state">正在打开作品……</div><ShareCard v-if="shareOpen&&shareContent" :content="shareContent" @close="shareOpen=false"/></div></template>
